ALTER TABLE redacoes ADD COLUMN IF NOT EXISTS portfolio_visivel TINYINT(1) NOT NULL DEFAULT 1;
CREATE TABLE IF NOT EXISTS redacao_anotacoes (id_anotacao INT AUTO_INCREMENT PRIMARY KEY,id_redacao INT NOT NULL,criado_por INT NOT NULL,inicio_texto INT UNSIGNED NOT NULL,fim_texto INT UNSIGNED NOT NULL,trecho VARCHAR(500) NOT NULL,comentario TEXT NOT NULL,tipo ENUM('ELOGIO','SUGESTAO','DUVIDA','CORRECAO') NOT NULL DEFAULT 'SUGESTAO',resolvida TINYINT(1) NOT NULL DEFAULT 0,criada_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_anotacao_redacao(id_redacao,resolvida,criada_em),CONSTRAINT fk_ra_redacao FOREIGN KEY(id_redacao) REFERENCES redacoes(id_redacao) ON DELETE CASCADE,CONSTRAINT fk_ra_autor FOREIGN KEY(criado_por) REFERENCES usuarios(id_usuario)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
